#include "exploration/DiscoveryFilingRuntime.hpp"
#include "core/Saturating.hpp"
#include <algorithm>
#include <cmath>
#include <cctype>
namespace elysium::exploration{
bool DiscoveryFilingRuntime::validName(const std::string&s,const NamingPolicy&p)const{if(s.empty())return false;if(p.maximumUtf8Bytes&&s.size()>p.maximumUtf8Bytes)return false;if(!p.allowLeadingTrailingSpace&&!s.empty()&&(std::isspace(static_cast<unsigned char>(s.front()))||std::isspace(static_cast<unsigned char>(s.back()))))return false;for(unsigned char c:s)if(c<0x20||c==0x7f)return false;return true;}bool DiscoveryFilingRuntime::canRename(const DiscoveryIdentity&d,std::uint64_t a,bool inst)const{switch(d.renameAuthority){case RenameAuthority::DiscovererOnly:return a==d.discovererStableId;case RenameAuthority::OwnerOrDiscoverer:return a==d.discovererStableId||a==d.ownerStableId;case RenameAuthority::Institutional:return inst;case RenameAuthority::Locked:return false;}return false;}
bool DiscoveryFilingRuntime::publishReward(FilingRewardDefinition d){if(!std::isfinite(d.standingDelta))return false;d.standingDelta=elysium::safe::finiteClamp(d.standingDelta,-elysium::safe::PublishedScalarCeiling,elysium::safe::PublishedScalarCeiling);rewards_[d.destination]=d;return true;}FilingFailure DiscoveryFilingRuntime::discover(DiscoveryIdentity d,const NamingPolicy&p){if(!d.stableTargetId||!d.proceduralIdentityKey||!d.discovererStableId||!validName(d.displayName,p))return FilingFailure::InvalidName;if(discoveries_.contains(d.stableTargetId))return FilingFailure::PermissionDenied;discoveries_[d.stableTargetId]=std::move(d);return FilingFailure::None;}FilingFailure DiscoveryFilingRuntime::rename(std::uint64_t id,std::uint64_t a,std::string n,const NamingPolicy&p,bool inst){auto i=discoveries_.find(id);if(i==discoveries_.end())return FilingFailure::MissingDiscovery;if(!validName(n,p))return FilingFailure::InvalidName;if(!canRename(i->second,a,inst))return FilingFailure::PermissionDenied;i->second.displayName=std::move(n);i->second.revision=elysium::safe::saturatingIncrement(i->second.revision);return FilingFailure::None;}FilingFailure DiscoveryFilingRuntime::begin(FilingTransaction t){if(!t.stableId||!t.discoveryStableId||!t.authorStableId)return FilingFailure::InvalidTransactionState;if(transactions_.contains(t.stableId))return FilingFailure::DuplicateTransaction;if(!discoveries_.contains(t.discoveryStableId))return FilingFailure::MissingDiscovery;if(!rewards_.contains(t.destination))return FilingFailure::MissingRewardProfile;if(std::any_of(history_.begin(),history_.end(),[&](const auto&h){return h.discoveryStableId==t.discoveryStableId;}))return FilingFailure::AlreadyFiled;t.state=FilingState::Requested;t.revision=1;transactions_[t.stableId]=t;return FilingFailure::None;}FilingOutcome DiscoveryFilingRuntime::commit(std::uint64_t id){FilingOutcome o;auto i=transactions_.find(id);if(i==transactions_.end()||i->second.state!=FilingState::Requested){o.failure=FilingFailure::InvalidTransactionState;return o;}auto&t=i->second;if(std::any_of(history_.begin(),history_.end(),[&](const auto&h){return h.discoveryStableId==t.discoveryStableId;})){o.failure=FilingFailure::AlreadyFiled;return o;}const auto&r=rewards_.at(t.destination);t.state=FilingState::Committed;t.revision=elysium::safe::saturatingIncrement(t.revision);history_.push_back({t.stableId,t.discoveryStableId,t.authorStableId,t.destination,r.credits,r.propagateCharts,r.exposeExternally,r.standingDelta,r.standingLedger});o.committed=true;o.creditsGrant=r.credits;o.chartPropagationRequest=r.propagateCharts;o.externalExposure=r.exposeExternally;o.standing={r.standingLedger,r.standingDelta,t.discoveryStableId};return o;}bool DiscoveryFilingRuntime::rollback(std::uint64_t id){auto i=transactions_.find(id);if(i==transactions_.end()||i->second.state!=FilingState::Requested)return false;i->second.state=FilingState::RolledBack;i->second.revision=elysium::safe::saturatingIncrement(i->second.revision);return true;}const DiscoveryIdentity*DiscoveryFilingRuntime::find(std::uint64_t id)const{auto i=discoveries_.find(id);return i==discoveries_.end()?nullptr:&i->second;}FilingSnapshot DiscoveryFilingRuntime::snapshot()const{FilingSnapshot s;for(auto&[_,x]:discoveries_)s.discoveries.push_back(x);for(auto&[_,x]:rewards_)s.rewards.push_back(x);for(auto&[_,x]:transactions_)s.transactions.push_back(x);s.history=history_;return s;}bool DiscoveryFilingRuntime::restore(const FilingSnapshot&s){DiscoveryFilingRuntime r;for(auto x:s.rewards)if(!r.publishReward(x))return false;NamingPolicy permissive{};for(auto x:s.discoveries)if(r.discover(std::move(x),permissive)!=FilingFailure::None)return false;for(auto x:s.transactions){if(!x.stableId||!r.discoveries_.contains(x.discoveryStableId)||r.transactions_.contains(x.stableId))return false;r.transactions_[x.stableId]=x;}r.history_=s.history;std::sort(r.history_.begin(),r.history_.end(),[](const auto&a,const auto&b){return a.transactionStableId<b.transactionStableId;});for(std::size_t i=1;i<r.history_.size();++i)if(r.history_[i-1].discoveryStableId==r.history_[i].discoveryStableId)return false;*this=std::move(r);return true;}
} // namespace elysium::exploration
